(6899053, 1039089, 104230, '<td valign="top">Great image. Interesting light that picks up the textures in his face and sweater.  I never vote on Robert''s images, and this got my highest score in this challenge.  Congratulations on the well deserved ribbon.</td>', 'Great image. Interesting light that picks up the textures in his face and sweater.  I never vote on Robert''s images, and this got my highest score in this challenge.  Congratulations on the well deserved ribbon.', '2012-11-05 18:01:38.000000', NULL, 0),
(6899054, 1038822, 104230, '<td valign="top">I have to echo what Mark said, I love the lines/perspective, reflections, and posture.  Congratulations on the top ten finish.</td>', 'I have to echo what Mark said, I love the lines/perspective, reflections, and posture.  Congratulations on the top ten finish.', '2012-11-05 18:04:51.000000', NULL, 0),
