(6899076, 1039161, 19825, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Luci11e:</b></div><hr/><i> this looks to be art as opposed to a meer photo </i></td></tr></table> <br/>Sadly, it looks like the average voter was looking for a mere photo. Fine art, indeed. Love the energy and contrast in this. Nice shot.</td>', 'Originally posted by Luci11e: this looks to be art as opposed to a meer photo  Sadly, it looks like the average voter was looking for a mere photo. Fine art, indeed. Love the energy and contrast in this. Nice shot.', '2012-11-05 18:34:03.000000', NULL, 0),
(6899078, 1039232, 135697, '<td valign="top">thank you to everyone! really appreciate the Top Ten. :O) I was out shooting anyway, i love to see new ways of using my Fisheye 8mm lens fully manual, and well convenience written on it and well it was a must shot, a one take on the fly and the storekeeper walked into the shot just as i took it so it wasnt until after i took it that i saw him standing there! one of those moments you just dont plan in one sense.. the angle was planned and composed but findng the store completely empty of people was funny i thought, a bit of irony! ;O)</td>', 'thank you to everyone! really appreciate the Top Ten. :O) I was out shooting anyway, i love to see new ways of using my Fisheye 8mm lens fully manual, and well convenience written on it and well it was a must shot, a one take on the fly and the storekeeper walked into the shot just as i took it so it wasnt until after i took it that i saw him standing there! one of those moments you just dont plan in one sense.. the angle was planned and composed but findng the store completely empty of people was funny i thought, a bit of irony! ;O)', '2012-11-05 18:38:07.000000', NULL, 0),
(6899079, 1039232, 135697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by vawendy:</b></div><hr/><i> This was one of my favs -- I really liked the distortion! Congrats on the top 10. :) </i></td></tr></table> <br/> <br/>Thanks really appreciate it</td>', 'Originally posted by vawendy: This was one of my favs -- I really liked the distortion! Congrats on the top 10. :)   Thanks really appreciate it', '2012-11-05 18:39:23.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6899080, 1039232, 135697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Neat:</b></div><hr/><i> Hey Top ten awesome stuff! </i></td></tr></table> <br/> <br/>thanks :O)</td>', 'Originally posted by Neat: Hey Top ten awesome stuff!   thanks :O)', '2012-11-05 18:40:02.000000', NULL, 0),
(6899081, 1039232, 135697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by jomari:</b></div><hr/><i> Congrats on TT. Cool shot. </i></td></tr></table> <br/> <br/>thanks its great to be on the site and participating with so many talented photographers, i hope i can bring my own uniqueness to the site :)</td>', 'Originally posted by jomari: Congrats on TT. Cool shot.   thanks its great to be on the site and participating with so many talented photographers, i hope i can bring my own uniqueness to the site :)', '2012-11-05 18:41:40.000000', NULL, 0),
(6899082, 1039232, 135697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tanguera:</b></div><hr/><i> Is this a store within a store? Perfect use for fish eye </i></td></tr></table> <br/> <br/>thanks its on the main street of the central city''s erm of one the many cross sections so perfect for this view/angle/lens</td>', 'Originally posted by tanguera: Is this a store within a store? Perfect use for fish eye   thanks its on the main street of the central city''s erm of one the many cross sections so perfect for this view/angle/lens', '2012-11-05 18:43:44.000000', NULL, 0),
(6899083, 1039232, 135697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nam:</b></div><hr/><i> Nice lens choice to bring interest to a challenge topic that apparently didn''t have much.  I especially like being able to see all the way down the street on the left side of the frame.  The clerk behind the counter is a nice touch, too.  Small matter because it almost is, but I''m wondering why you didn''t go black and white?  Voted earlier. </i></td></tr></table> <br/> <br/>Thanks again and that goes for everyone who comments and voted for it! Really appreciate the feedback.<br/> <br/>the clerk just appeared in shot as i took it.. fortunately he was still when i clicked hahaha one shot. i thought about black and white i thought about many different possible but i love it the way it is, and thought so many photos can be done like that and have seen them that way on here and i love B&amp;W but i wanted to be different if that makes sense, but thanks for questioning :O) hope that answered that one :O)</td>', 'Originally posted by nam: Nice lens choice to bring interest to a challenge topic that apparently didn''t have much.  I especially like being able to see all the way down the street on the left side of the frame.  The clerk behind the counter is a nice touch, too.  Small matter because it almost is, but I''m wondering why you didn''t go black and white?  Voted earlier.   Thanks again and that goes for everyone who comments and voted for it! Really appreciate the feedback. the clerk just appeared in shot as i took it.. fortunately he was still when i clicked hahaha one shot. i thought about black and white i thought about many different possible but i love it the way it is, and thought so many photos can be done like that and have seen them that way on here and i love B&W but i wanted to be different if that makes sense, but thanks for questioning :O) hope that answered that one :O)', '2012-11-05 18:48:02.000000', NULL, 0),
